#!/usr/bin/perl
use strict;
use warnings;
use File::Path qw(make_path);

my $out = 'wrk';
if (@ARGV == 2 && $ARGV[0] eq '--out') {
   $out = $ARGV[1];
}
elsif (@ARGV != 0) {
   die "usage: $0 [--out DIR]\n";
}

make_path($out) if !-d $out;

my $marker = '__N65_GENASM_FILE_6c7c4ce6a2404b4ea0a5__';
my $current;
my %file;
while (defined(my $line = <DATA>)) {
   if ($line =~ /^\Q$marker\E\s+(.+)$/) {
      $current = $1;
      chomp $current;
      die "$0: duplicate generated file $current\n" if exists $file{$current};
      $file{$current} = '';
      next;
   }
   die "$0: data before first file marker\n" if !defined $current;
   $file{$current} .= $line;
}

sub reverse_copy_loop {
   my ($label, $size) = @_;
   return sprintf(<<'ASM', $size - 1, $label, $size, $label);
    lda #0
    sta tmp0
    lda #$%02x
    sta tmp1
@%s_loop:
    ldy tmp1
    lda (ptr0), y
    ldy tmp0
    sta (ptr1), y
    inc tmp0
    dec tmp1
    lda tmp0
    cmp #$%02x
    bne @%s_loop
