   my $lhs_off = 6;
   my $rhs_off = 6 + $size;
   my $dst_off = 6 + ($size * 2);
   my $lhs_arg = $frame - $lhs_off;
   my $rhs_arg = $frame - $rhs_off;
   my $dst_arg = $frame - $dst_off;
   my $sym = "_${prefix}be_${op}";
   my $le_sym = "_${prefix}_${op}";
   my $lhs_loop = reverse_copy_loop('lhs', $size);
   my $rhs_loop = reverse_copy_loop('rhs', $size);
   my $dst_loop = reverse_copy_loop('dst', $size);
   my @args = (
      $le_sym, $sym,
      $sym, $frame,
      $frame,
      $lhs_arg, $lhs_loop,
      $rhs_arg, $rhs_loop,
      $lhs_arg,
      $rhs_arg,
      $dst_arg,
      $le_sym,
