for my $fmt ([ 'f16', 2 ], [ 'f32', 4 ], [ 'f64', 8 ]) {
   my ($prefix, $size) = @$fmt;
   for my $op (qw(add sub mul div)) {
      my $name = "_${prefix}be_${op}.s";
      die "$0: duplicate generated file $name\n" if exists $file{$name};
      $file{$name} = be_wrapper($prefix, $size, $op);
   }
}

for my $name (sort keys %file) {
   die "$0: unsafe generated filename $name\n" if $name =~ m{/} || $name =~ /\.\./;
   my $path = "$out/$name";
   open(my $fh, '>', $path) or die "$0: cannot write $path: $!\n";
   print {$fh} $file{$name};
   close($fh) or die "$0: cannot close $path: $!\n";
}

print "generated ", scalar(keys %file), " builtin float assembly files in $out\n";

